Given an unsorted doubly linked list containing n nodes, the task is to remove duplicate nodes while preserving the original order.Examples: Input: Doubly Linked List = 1 <-> 2 <-> 3 <-> 2 <-> 4Output: Doubly Linked List = 1 <-> 2 <-> 3 <-> 4Removal of duplicate node 2 from Doubly Linked ListInput: Doubly Linked List = 8 <-> 4 <-> 4 <-> 6 <-> 4 <-> 8 <-> 4 <-> 10 <-> 12 <-> 12Output: Doubly Linked List = 8 <-> 4 <-> 6 <-> 10 <-> 12Table of Content[Naive Approach] Using Nested Loops - O(n^2) Time and O(1) Space[Expected Approach] Using HashSet - O(n) Time and O(n) Space[Naive Approach] Using Nested Loops - O(n^2) Time and O(1) SpaceThe idea is to use two nested loops. The outer loop is used to pick the elements one by one and the inner loop compares the picked element with the rest of the elements in the doubly linked list. Below is the implementation of the above approach:
            C++

    // C++ program to remove duplicates from an 
// unsorted doubly linked list

#include <iostream>
using namespace std;

class Node {
public:
    int data;
    Node* next;
  	Node* prev;

    Node(int val) {
        data = val;
        next = nullptr;
        prev = nullptr;
    }
};

// Function to remove duplicates using nested loops
Node* removeDuplicates(Node* head) {
    Node* curr = head; 

    // Traverse each node in the list
    while (curr != nullptr) {
        Node* temp = curr; 

        // Traverse the remaining nodes to find and 
        // remove duplicates
        while (temp->next != nullptr) {

            // Check if the next node has the same 
            // data as the current node
            if (temp->next->data == curr->data) {

                // Duplicate found, remove it
                Node* duplicate = temp->next;  
                temp->next = temp->next->next;  

                // Update the previous pointer of the
                // next node, if it exists
                if (temp->next != nullptr)
                    temp->next->prev = temp;

                // Free the memory of the duplicate node
                delete duplicate;
            } 
          	else {

              	// If the next node has different data from 
              	// the current node, move to the next node
                temp = temp->next;
            }
        }

        // Move to the next node in the list
        curr = curr->next;
    }
    return head;
}

void printList(Node* head) {
    Node* curr = head;
    while (curr != nullptr) {
        cout << curr->data << " ";
        curr = curr->next;
    }
    cout << endl;
}

int main() {

    // Create a doubly linked list:
    // 1 <-> 2 <-> 3 <-> 2 <-> 4
    Node* head = new Node(1);
    head->next = new Node(2);
    head->next->prev = head;
    head->next->next = new Node(3);
    head->next->next->prev = head->next;
    head->next->next->next = new Node(2);
    head->next->next->next->prev = head->next->next;
    head->next->next->next->next = new Node(4);
    head->next->next->next->next->prev = head->next->next->next;

    head = removeDuplicates(head);

    printList(head);

    return 0;
}


